public class Complex_reciprocal_TriageGen0Test {

    private static final double EPSILON = 1e-10;





    @Test
    public void testReciprocal_IsInfinite() {
        // Test with infinite real part
        Complex complexInfReal = new Complex(Double.POSITIVE_INFINITY, 0.0);
        Complex result1 = complexInfReal.reciprocal();
        Assert.assertEquals("Reciprocal of infinity should be zero", Complex.ZERO, result1);

        // Test with infinite imaginary part
        Complex complexInfImag = new Complex(0.0, Double.NEGATIVE_INFINITY);
        Complex result2 = complexInfImag.reciprocal();
        Assert.assertEquals("Reciprocal of infinite imaginary should be zero", Complex.ZERO, result2);
    }










}

package org.apache.commons.math3.complex;

import java.io.*;
