import org.junit.*;
import org.junit.Assert;
import org.junit.Test;
import static org.junit.Assert.*;

public class Complex_reciprocal_TriageGen0Test {

    private static final double EPSILON = 1e-10;







    @Test
    public void testReciprocal_SmallImaginaryPart() {
        // This triggers the branch: FastMath.abs(real) < FastMath.abs(imaginary)
        // Let real = 1.0, imaginary = 2.0
        // q = 1/2 = 0.5
        // scale = 1 / (1 * 0.5 + 2) = 1 / 2.5 = 0.4
        // result = (0.4 * 0.5, -0.4) = (0.2, -0.4)
        Complex complex = new Complex(1.0, 2.0);
        Complex result = complex.reciprocal();

        Assert.assertEquals(0.2, result.getReal(), EPSILON);
        Assert.assertEquals(-0.4, result.getImaginary(), EPSILON);
    }








}

