import org.apache.commons.math3.util.FastMath;
import org.apache.commons.math3.util.MathUtils;
import org.junit.*;
import org.junit.Assert;
import org.junit.Test;
import static org.junit.Assert.*;

public class Complex_reciprocal_TriageGen0Test {

    private static final double EPSILON = 1e-10;









    @Test
    public void testReciprocal_LargeImaginaryPart() {
        // This triggers the branch: FastMath.abs(real) < FastMath.abs(imaginary)
        // Let real = -1.0, imaginary = 10.0
        // q = -1/10 = -0.1
        // scale = 1 / (-1 * -0.1 + 10) = 1 / 10.1
        // result = (scale * q, -scale)
        Complex complex = new Complex(-1.0, 10.0);
        Complex result = complex.reciprocal();

        double q = -1.0 / 10.0;
        double scale = 1.0 / (-1.0 * q + 10.0);
        Assert.assertEquals(scale * q, result.getReal(), EPSILON);
        Assert.assertEquals(-scale, result.getImaginary(), EPSILON);
    }






}

