public class Complex_reciprocal_TriageGen0Test {

    private static final double EPSILON = 1e-10;















    @Test
    public void testReciprocal_Equality() {
        // Verify that reciprocal(reciprocal(z)) approx z
        Complex complex = new Complex(3.0, 4.0);
        Complex reciprocal = complex.reciprocal();
        Complex doubleReciprocal = reciprocal.reciprocal();

        Assert.assertEquals(complex.getReal(), doubleReciprocal.getReal(), EPSILON);
        Assert.assertEquals(complex.getImaginary(), doubleReciprocal.getImaginary(), EPSILON);
    }
}
